/*deleteMasterMpIfObPoAlter*/
 DELETE FROM EAI.IF_OBBE_PO_CHG
  WHERE BUYER = #{BUYER}
	AND LEGACY_PO_NO      = NVL(#{LEGACY_PO_NO},' ')
	AND BUYER_ITEM_NO     = NVL(#{BUYER_ITEM_NO},' ')


	/*updateMasterMpIfOrderFlag*/
	UPDATE EAI.IF_OBBE_PO_CHG 
	   SET IF_FLAG = 'T'
     WHERE BUYER = #{BUYER}
       AND LEGACY_PO_NO = #{LEGACY_PO_NO}
       AND BUYER_ITEM_NO = #{BUYER_ITEM_NO}


	/*deleteMasterMpIfGrCreate*/
	 DELETE FROM EAI.IF_OBBE_PO_CHG 
	  WHERE BUYER = #{BUYER}
	   AND LEGACY_PO_NO = #{LEGACY_PO_NO}
       AND BUYER_ITEM_NO = #{BUYER_ITEM_NO}
